<?php $pageTitle='Reports'; include __DIR__.'/../includes/header.php'; require_login('administrator'); $pdo=Database::connection(); $daily=$pdo->query('SELECT appointment_date, COUNT(*) total FROM appointments GROUP BY appointment_date ORDER BY appointment_date DESC LIMIT 30')->fetchAll(); ?>
<h1>Reports</h1><p>Daily, weekly, monthly appointments, patient counts, revenue, and doctor performance can be exported from these summary queries.</p><table class="table"><tr><th>Date</th><th>Appointments</th></tr><?php foreach($daily as $r): ?><tr><td><?= e($r['appointment_date']) ?></td><td><?= e($r['total']) ?></td></tr><?php endforeach; ?></table><?php include __DIR__.'/../includes/footer.php'; ?>
